S = "Hakeem Force Academy"
QS = [
 (S, "In which month and year was the Lucknow Pact signed between the Muslim League and the Indian National Congress?", ["December 1916", "March 1940", "October 1906", "August 1947"], 0,
  "The Lucknow Pact was agreed at the joint sessions of the Congress and the Muslim League in Lucknow in December 1916.", "Quaid-e-Azam Muhammad Ali Jinnah is known as the ambassador of Hindu-Muslim unity for this pact.", [117]),
 (S, "Who first introduced the photostat (photocopying) machine?", ["Chester Carlson", "Thomas Edison", "Graham Bell", "Johannes Gutenberg"], 0,
  "Chester Carlson, an American inventor, invented the dry photocopying process called xerography in 1938.", "The first commercial xerographic copier was released by the Xerox company in 1959.", [610]),
 (S, "How many Madni surahs are there in the Holy Quran, according to the commonly accepted count?", ["28", "86", "114", "10"], 0,
  "Of the 114 surahs, 86 are Makki and 28 are Madni, revealed after the Hijrah.", "Scholars differ slightly on the count of some surahs, but 28 is the most common answer.", [386, 138]),
 (S, "What was the last major ghazwa of the Muslims against the Quraish of Makkah?", ["Conquest of Makkah (Fath Makkah)", "Battle of Badr", "Battle of Uhud", "Battle of the Trench"], 0,
  "The Muslims conquered Makkah in 8 AH (630 CE), which ended the war with the Quraish.", "The Prophet (PBUH) forgave the people of Makkah after the conquest.", [3333]),
 (S, "What was the old name of Makkah mentioned in the Holy Quran?", ["Yathrib", "Bakkah", "Taif", "Tabuk"], 1,
  "Surah Aal-e-Imran (3:96) calls the place of the first house of worship Bakkah, which is Makkah.", "Madinah was formerly called Yathrib.", [120]),
 (S, "There are 30 passengers in a bus and 2/3 of them are male. How many are women?", ["20", "15", "10", "12"], 2,
  "Males = 2/3 x 30 = 20. Women = 30 - 20 = 10.", "The women are 1/3 of all passengers.", [440]),
 (S, "In a class of 30 students, 2/3 are male. What is the percentage of males?", ["33.33%", "66.67%", "60%", "75%"], 1,
  "Percentage = 2/3 x 100 = 66.67%.", "The remaining 1/3 are females, which is 33.33%.", [1936]),
 (S, "According to the Holy Quran, killing one innocent person is like killing whom?", ["All of humanity", "One family", "One tribe", "One city"], 0,
  "Surah Al-Maidah (5:32) says that whoever kills one innocent soul, it is as if he killed all of mankind.", "The same verse says saving one life is like saving all of mankind.", [2561]),
 (S, "What is the meaning of the idiom \"man of straw\"?", ["A person of no substance or strength", "A very rich man", "A farmer", "A brave soldier"], 0,
  "A man of straw is a weak person or an imaginary opponent with no real substance.", "Straw is light and weak, which is why the idiom describes someone without real strength.", [3010]),
 (S, "Manchar Lake, the largest freshwater lake of Pakistan, is located in which district of Sindh?", ["Dadu", "Sukkur", "Thatta", "Larkana"], 0,
  "Manchar Lake lies in Dadu district of Sindh, west of the Indus River near Sehwan.", "It is among the largest freshwater lakes in South Asia.", [1999, 766, 3542]),
 (S, "Ahmed got 15 marks out of 60. What is his percentage?", ["20%", "30%", "15%", "25%"], 3,
  "Percentage = 15/60 x 100 = 25%.", "15/60 simplifies to 1/4, which is 25%.", [171, 1868]),
 (S, "Which daughter of Hazrat Umar (RA) was married to the Holy Prophet (PBUH)?", ["Hazrat Aisha (RA)", "Hazrat Hafsa (RA)", "Hazrat Zainab (RA)", "Hazrat Sauda (RA)"], 1,
  "Hazrat Hafsa (RA), daughter of Hazrat Umar (RA), married the Prophet (PBUH) in 3 AH.", "She was one of the Mothers of the Believers and kept the first written copy of the Quran after Hazrat Abu Bakr (RA).", [3731]),
 (S, "How many Muslims were martyred in the Battle of Uhud?", ["14", "70", "313", "100"], 1,
  "About 70 Muslims were martyred at Uhud, including Hazrat Hamza (RA).", "Only 14 Muslims were martyred at Badr.", [716, 1751]),
 (S, "Which woman is the only one whose personal name is mentioned in the Holy Quran?", ["Hazrat Maryam (AS)", "Hazrat Khadija (RA)", "Hazrat Aisha (RA)", "Hazrat Fatima (RA)"], 0,
  "The name Maryam appears in the Quran about 34 times, and no other woman is named.", "Surah Maryam (Chapter 19) is named after her.", [824]),
 (S, "Which wife of the Holy Prophet (PBUH) was known as Umm-ul-Masakin (Mother of the Poor)?", ["Hazrat Zainab bint Khuzaimah (RA)", "Hazrat Hafsa (RA)", "Hazrat Umm Salma (RA)", "Hazrat Safiyya (RA)"], 0,
  "Hazrat Zainab bint Khuzaimah (RA) was famous for feeding and helping the poor, so she was called Umm-ul-Masakin.", "She died soon after marriage, during the lifetime of the Prophet (PBUH).", [4073, 4423]),
 (S, "Where is Masjid Qiblatain (Masjid-e-Zulqiblatain) located?", ["Madinah", "Makkah", "Jerusalem", "Taif"], 0,
  "It is in Madinah, where the Prophet (PBUH) was leading prayer when the command came to turn towards the Kaaba.", "The qibla was changed from Bait-ul-Muqaddas to the Kaaba in 2 AH.", [3576]),
 (S, "What is the SI unit of mass?", ["Newton", "Gram", "Kilogram", "Pound"], 2,
  "The SI base unit of mass is the kilogram (kg).", "Weight is a force and is measured in newtons.", [3246]),
 (S, "Who has taken the most wickets in Test cricket?", ["Muttiah Muralitharan", "Wasim Akram", "Shane Warne", "James Anderson"], 0,
  "Muttiah Muralitharan of Sri Lanka took 800 Test wickets, the highest ever.", "Shane Warne is second with 708 and James Anderson third with 704; Wasim Akram took 414.", [4143, 1202]),
 (S, "Who is the ODI captain of the Pakistan cricket team as of 2026?", ["Shaheen Shah Afridi", "Mohammad Rizwan", "Babar Azam", "Salman Ali Agha"], 0,
  "The PCB appointed fast bowler Shaheen Shah Afridi as ODI captain in early 2026, and he still leads the side.", "Mohammad Rizwan was the ODI captain before him, from late 2024.", [4235]),
 (S, "What is the correct relation between the arithmetic mean (A.M), geometric mean (G.M) and harmonic mean (H.M) of positive numbers?", ["A.M is greater than or equal to G.M, which is greater than or equal to H.M", "H.M is greater than or equal to G.M, which is greater than or equal to A.M", "G.M is greater than or equal to A.M, which is greater than or equal to H.M", "All three are always different and unrelated"], 0,
  "For positive numbers, A.M is at least G.M, which is at least H.M, with equality only when all numbers are equal.", "For two numbers a and b, G.M squared equals A.M times H.M.", [2497]),
 (S, "What are the signs for greater than and less than called in mathematics?", ["Inequality symbols", "Equality symbols", "Operators of addition", "Ratio signs"], 0,
  "Signs like greater than and less than show that two quantities are not equal, so they are inequality symbols.", "The equals sign shows equality.", [3149]),
]
